                return True
        if u == d or abs(u - d) <= 2: #situation 2 and situation 3
            if t % 2:
                return False
            else:
                return True
        return True #default situation

class Solution:
    def smallestSubsequence(self, s: str, k: int, letter: str, r: int) -> str:
        n_letters = len([c for c in s if c == letter])
        stack = []

        for i, c in enumerate(s):
            while stack and stack[-1] > c and (len(s) - i + len(stack) > k) and (stack[-1] != letter or n_letters > r):
                d = stack.pop()
                if d == letter:
                    r += 1

            if len(stack) < k:
                if c == letter:
                    stack.append(c)
                    r -= 1
                elif k - len(stack) > r:
                    stack.append(c)

            if c == letter:
                n_letters -= 1

        return ''.join(stack)

class Solution:
    def smallestSubsequence(self, s, k, letter, repetition):
        stk = []
        suffix = [0]*(len(s)+1)
        for i in reversed(range(len(suffix)-1)):
            suffix[i] = suffix[i+1]+(s[i] == letter)
        for i, c in enumerate(s): 
            while stk and stk[-1] > c and len(stk)+(len(s)-i) > k and (stk[-1] != letter or repetition+1 <= suffix[i]):
                repetition += (stk.pop() == letter)
            if len(stk) < min(k-(repetition-(c == letter)), k):
                repetition -= (c == letter)
                stk.append(c)
        return "".join(stk)

